import styled from '@emotion/styled';
import { theme } from 'theme';

export const StyledErrorStateContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'center',
  alignItems: 'center',
  gap: '16px',
  paddingTop: '64px',
  paddingBottom: '64px',
  width: '100%',

  '& img': {
    width: '200px',
    height: '200px',
  },

  '& p': {
    fontFamily: theme.fonts.paragraph,
    fontWeight: 400,
    fontSize: '20px',
    lineHeight: '1.4',
    letterSpacing: 0,
    textAlign: 'center',
    color: theme.colors.interfaceLabelPrimary,
    margin: 0,
  },
});
